VR(a){var s=null
return A.aG(a,s,this.a,s,"1 \u0928\u093f\u092a\u091f\u093e\u092f\u093e \u0917\u092f\u093e \u091a\u0947\u0915",""+a+" \u0928\u093f\u092a\u091f\u093e\u090f \u0917\u090f \u091a\u0947\u0915",s,s)+" \u2014 \u091c\u094d\u092f\u093e\u0926\u093e\u0924\u0930 Manager.io \u0938\u0947 \u0906\u092f\u093e\u0924\u093f\u0924 \u2014 \u0909\u0928 \u0932\u0947\u091c\u0930 \u092a\u094d\u0930\u0935\u093f\u0937\u094d\u091f\u093f\u092f\u094b\u0902 \u0938\u0947 \u0928\u0939\u0940\u0902 \u091c\u0941\u0921\u093c\u0947 \u0939\u0948\u0902 \u091c\u093f\u0928\u0915\u093e \u0935\u0947 \u092a\u094d\u0930\u0924\u093f\u0928\u093f\u0927\u093f\u0924\u094d\u0935 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902\u0964 \u0905\u092d\u0940 \u090f\u0915 \u0915\u094b \u0939\u091f\u093e\u0928\u0947 \u0938\u0947 \u0915\u0947\u0935\u0932 \u0926\u093f\u0916\u093e\u0908 \u0926\u0947\u0928\u0947 \u0935\u093e\u0932\u093e \u091a\u0947\u0915 \u0939\u091f \u091c\u093e\u090f\u0917\u093e, \u0907\u0938\u0915\u0947 \u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 \u092a\u0948\u0938\u0947 (\u0926\u0947\u092f, \u092a\u094d\u0930\u093e\u092a\u094d\u092f, \u0928\u0915\u0926 \u0914\u0930 \u092c\u0948\u0902\u0915) \u092a\u0942\u0930\u0940 \u0924\u0930\u0939 \u0938\u0947 \u0905\u091b\u0942\u0924\u0947 \u0930\u0939 \u091c\u093e\u090f\u0902\u0917\u0947\u0964 \u0939\u0930 \u090f\u0915 \u0915\u094b \u0909\u0938\u0915\u0940 \u0935\u093e\u0938\u094d\u0924\u0935\u093f\u0915 \u092a\u094d\u0930\u0935\u093f\u0937\u094d\u091f\u093f\u092f\u094b\u0902 \u0938\u0947 \u091c\u094b\u0921\u093c\u0924\u093e \u0939\u0948 \u0924\u093e\u0915\u093f \u0905\u092c \u0938\u0947 \u0939\u091f\u093e\u0928\u093e \u0938\u0939\u0940 \u0922\u0902\u0917 \u0938\u0947 \u0915\u093e\u092e \u0915\u0930\u0947 \u2014 \u0916\u0941\u0926 \u0915\u094b\u0908 \u092a\u0948\u0938\u093e \u0928\u0939\u0940\u0902 \u0939\u093f\u0932\u093e\u0924\u093e\u0964"},
gV6(){return"\u0932\u093f\u0902\u0915"},
gVa(){return"\u092c\u093f\u0928\u093e \u0928\u093f\u092f\u0924 \u0924\u093e\u0930\u0940\u0916 \u0935\u093e\u0932\u0947 \u091a\u093e\u0932\u093e\u0928"},
