gMm(){return"\u0642\u0627\u0628\u0644 \u062a\u0631\u0645\u06cc\u0645\u060c \u0642\u0627\u0628\u0644 \u06af\u0631\u0648\u067e \u2014 \u0645\u062b\u0644\u0627\u064b \u06af\u0627\u0691\u06cc \u06a9\u06d2 \u0627\u062e\u0631\u0627\u062c\u0627\u062a > \u06af\u0627\u0691\u06cc 1 > \u067e\u06cc\u0679\u0631\u0648\u0644"},
gMD(){return"\u0633\u06cc\u0644\u0632\u0645\u06cc\u0646 \u0634\u0646\u0627\u062e\u062a \u06a9\u0627 \u062c\u0627\u0626\u0632\u06c1"},
gMC(){return"\u06a9\u0633\u0679\u0645\u0631\u0632\u060c \u0627\u0646\u0648\u0627\u0626\u0633\u0632\u060c \u0627\u0648\u0631 \u06a9\u0645\u06cc\u0634\u0646 \u0631\u06cc\u0679\u0633 \u067e\u0631 \u067e\u0631\u0627\u0646\u06d2 \u0633\u06cc\u0644\u0632\u0645\u06cc\u0646 \u0646\u0627\u0645\u0648\u06ba \u06a9\u0648 \u0627\u06cc\u06a9 \u062d\u0642\u06cc\u0642\u06cc \u0627\u0633\u0679\u0627\u0641 \u0627\u06a9\u0627\u0624\u0646\u0679 \u0633\u06d2 \u0645\u0646\u0633\u0644\u06a9 \u06a9\u0631\u06cc\u06ba"},
gMj(){return"\u062d\u0630\u0641 \u0634\u062f\u06c1 \u0644\u06cc\u0646 \u062f\u06cc\u0646"},
gMi(){return"\u06c1\u0631 \u062d\u0630\u0641 \u0634\u062f\u06c1 \u0627\u0646\u0648\u0627\u0626\u0633\u060c \u062e\u0631\u06cc\u062f\u0627\u0631\u06cc \u0627\u0646\u0648\u0627\u0626\u0633\u060c \u06a9\u0631\u06cc\u0688\u0679/\u0688\u06cc\u0628\u0679 \u0646\u0648\u0679 \u0627\u0648\u0631 \u0686\u06cc\u06a9 \u2014 \u06a9\u0633 \u0646\u06d2 \u062d\u0630\u0641 \u06a9\u06cc\u0627\u060c \u0627\u0648\u0631 \u06a9\u0628"},
gRg(){return"\u06cc\u06c1 \u0688\u06cc\u0648\u0627\u0626\u0633 \u0641\u0646\u06af\u0631 \u067e\u0631\u0646\u0679 \u06cc\u0627 \u0641\u06cc\u0633 \u0627\u0646 \u0644\u0627\u06a9 \u06a9\u0648 \u0633\u067e\u0648\u0631\u0679 \u0646\u06c1\u06cc\u06ba \u06a9\u0631\u062a\u06cc\u06d4"},
gRe(){return"\u0641\u0646\u06af\u0631 \u067e\u0631\u0646\u0679 / \u0641\u06cc\u0633 \u0627\u0646 \u0644\u0627\u06a9"},
gRd(){return"\u0627\u0633 \u0688\u06cc\u0648\u0627\u0626\u0633 \u067e\u0631 \u0627\u067e\u0646\u0627 \u067e\u0646 \u0679\u0627\u0626\u067e \u06a9\u0631\u0646\u0627 \u0686\u06be\u0648\u0691\u06cc\u06ba \u2014 \u062c\u0628 \u0628\u06be\u06cc \u06cc\u06c1 \u062a\u0635\u062f\u06cc\u0642 \u0646\u06c1\u06cc\u06ba \u06a9\u0631 \u067e\u0627\u062a\u0627 \u06a9\u06c1 \u06cc\u06c1 \u0622\u067e \u06c1\u06cc\u06ba\u060c \u06cc\u06c1 \u0622\u067e \u06a9\u06d2 \u067e\u0646 \u067e\u0631 \u0648\u0627\u067e\u0633 \u0686\u0644\u0627 \u062c\u0627\u062a\u0627 \u06c1\u06d2\u06d4"},
gRf(){return"\u0641\u0646\u06af\u0631 \u067e\u0631\u0646\u0679 / \u0641\u06cc\u0633 \u0627\u0646 \u0644\u0627\u06a9 \u0622\u0646 \u06a9\u0631\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u062a\u0635\u062f\u06cc\u0642 \u06a9\u0631\u06cc\u06ba"},
gSw(){return"\u06a9\u0645\u067e\u0646\u06cc / \u062f\u06a9\u0627\u0646 \u06a9\u0627 \u0646\u0627\u0645 *"},
gSv(){return"\u0636\u0631\u0648\u0631\u06cc \u2014 \u0622\u067e \u06a9\u06d2 \u0628\u0646\u0627\u0626\u06d2 \u06af\u0626\u06d2 \u06c1\u0631 \u062f\u0633\u062a\u0627\u0648\u06cc\u0632 \u067e\u0631 \u067e\u0631\u0646\u0679 \u06c1\u0648\u062a\u0627 \u06c1\u06d2"},
gSG(){return"\u0679\u06cc\u06af \u0644\u0627\u0626\u0646 (\u0627\u062e\u062a\u06cc\u0627\u0631\u06cc)"},
