gSs(){return"\u0641\u0648\u0631\u0627\u0646 \u062a\u0641\u0635\u06cc\u0644\u0627\u062a (\u0627\u062e\u062a\u06cc\u0627\u0631\u06cc)"},
gSr(){return"\u0641\u0648\u0631\u06cc \u0645\u0646\u062a\u0642\u0644\u06cc \u06a9\u06d2 \u0644\u06cc\u06d2 \u0622\u067e \u06a9\u0627 \u0641\u0648\u0631\u0627\u0646 \u0622\u0626\u06cc \u0688\u06cc / QR \u062d\u0648\u0627\u0644\u06c1"},
gSo(){return"\u062f\u0633\u062a\u0627\u0648\u06cc\u0632 \u0641\u0648\u0646\u0679"},
gGw(){return"\u062f\u0633\u062a\u0627\u0648\u06cc\u0632 \u06a9\u0627 \u0646\u0645\u0627\u06cc\u0627\u06ba \u0631\u0646\u06af"},
gGy(){return"\u0679\u06cc\u06af \u0644\u0627\u0626\u0646 \u0631\u0646\u06af"},
gSE(){return"\u06c1\u0631 \u062f\u0633\u062a\u0627\u0648\u06cc\u0632 \u067e\u0631 \u0622\u067e \u06a9\u06d2 \u0646\u0627\u0645 \u06a9\u06d2 \u0646\u06cc\u0686\u06d2 \u067e\u0631\u0646\u0679 \u06c1\u0648\u062a\u0627 \u06c1\u06d2"},
gSD(){return"\u0622\u067e \u06a9\u06d2 \u067e\u0631\u0646\u0679 \u0634\u062f\u06c1 \u062f\u0633\u062a\u0627\u0648\u06cc\u0632\u0627\u062a \u067e\u0631 \u06c1\u0631 \u0679\u06cc\u0628\u0644/\u0628\u0627\u06a9\u0633 \u0628\u0627\u0631\u0688\u0631 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0628\u06be\u06cc \u0627\u0633\u062a\u0639\u0645\u0627\u0644 \u06c1\u0648\u062a\u0627 \u06c1\u06d2 \u2014 \u067e\u0631\u0646\u0679 \u0644\u06d2 \u0622\u0624\u0679 \u062e\u0648\u062f \u06a9\u0628\u06be\u06cc \u0646\u06c1\u06cc\u06ba \u0628\u062f\u0644\u062a\u0627\u060c \u0635\u0631\u0641 \u06cc\u06c1 \u0627\u06cc\u06a9 \u0631\u0646\u06af\u06d4"},
gGz(){return"\u062f\u0633\u062a\u0627\u0648\u06cc\u0632 \u0679\u06cc\u06a9\u0633\u0679 \u0631\u0646\u06af"},
gSH(){return"\u0622\u0626\u0679\u0645 \u06a9\u06cc \u062a\u0641\u0635\u06cc\u0644\u0627\u062a\u060c \u067e\u062a\u06d2\u060c \u0631\u0642\u0648\u0645\u060c \u0627\u0648\u0631 \u062f\u06cc\u06af\u0631 \u0627\u06c1\u0645 \u0645\u062a\u0646"},
